console.log("Hello, JavaScript!");

function first() {
  console.log("first start");
  second();
  console.log("first end");
}
function second() {
  console.log("second runs inside first");
}
first();

var my_firstName = "John";
var _lastName$ = "Doe";
let $city = "New York";
console.log(my_firstName, _lastName$, $city);

const user = { name: "Asha" };
user.name = "Ravi";      // allowed - object is mutated
console.log(user);

try {
  user = {};             // re-assignment is not allowed
} catch (e) {
  console.log(e.name + ": " + e.message);
}

if (true) {
  var a = "var leaks";
  let b = "let stays inside";
}
console.log(a);
try {
  console.log(b);
} catch (e) {
  console.log("b is not defined here ->", e.name);
}

const values = [42, "hi", true, undefined, null, 10n, Symbol("id"), {}, [], function () {}, NaN];
values.forEach((v) => console.log(String(typeof v).padEnd(10), "->", typeof v === "symbol" ? "Symbol" : v));

console.log(Array.isArray([]), Array.isArray({}));
console.log(null == undefined, null === undefined);

const samples = [0, "", "0", [], {}, null, undefined, NaN, -1, "false"];
for (const s of samples) {
  console.log(typeof s === "string" ? `"${s}"` : s, "=>", Boolean(s));
}

console.log(parseInt("123"), parseInt("42.5"), parseInt("077"), parseInt("xyz"));
console.log(parseFloat("1.9abc"), Number("1.9abc"));
console.log(NaN === NaN, Number.isNaN(NaN), isNaN("vinod"), Number.isNaN("vinod"));
console.log(["1", "2", "3"].map(parseInt));
console.log(["1", "2", "3"].map(Number));
